func:
if (msg.payload.ac.flight && msg.payload.ac.flight.toString().includes("TEST") || msg.payload.ac.flight.toString().includes("GAFTT")) {
    return null;  // Drop the message
}
const time = new Date(Date.now()).toISOString();
//const staleTime = new Date(Date.now() + ((5 * 60 * 1000))).toISOString();
let latitude = typeof msg.payload.ac.rr_lat !== 'undefined' ? msg.payload.ac.rr_lat : msg.payload.ac.lat;
if (latitude == null){
    latitude = "0.0"
};
let longitude = typeof msg.payload.ac.rr_lon !== 'undefined' ? msg.payload.ac.rr_lon : msg.payload.ac.lon;
if (longitude == null){
    longitude = "0.0"
};

// Same TN + overlap bounding box used across the other flows. Emergency
// squawk queries (7500/7600/7700) are global with no server-side geographic
// filter, so this is applied here client-side instead. Also incidentally
// drops the "0.0,0.0" fallback case above, since Null Island is nowhere
// near Tennessee.
const TN_BBOX = { latMin: 34.3, latMax: 37.2, lonMin: -91.2, lonMax: -82.0 };
const latNum = parseFloat(latitude);
const lonNum = parseFloat(longitude);
if (!Number.isFinite(latNum) || !Number.isFinite(lonNum) ||
    latNum < TN_BBOX.latMin || latNum > TN_BBOX.latMax ||
    lonNum < TN_BBOX.lonMin || lonNum > TN_BBOX.lonMax) {
    return null;
}

let elevation = typeof msg.payload.ac.alt_geom !== 'undefined' ? msg.payload.ac.alt_geom * 0.3048 : msg.payload.ac.alt_baro;
const hexid = msg.payload.ac.hex
const reg = msg.payload.ac.r
const type = msg.payload.ac.t
const desc = msg.payload.ac.desc
const ownOp = msg.payload.ac.ownOp
const remarks = [
    "ID: " + hexid +
    "\nSquak: "+ msg.payload.ac.squawk +
    "\nReg: " + reg +
    "\nType: "+ type +
    "\nDesc: "+ desc +
    "\nOperator: " + ownOp +
    "\nFlight: https://www.flightaware.com/live/flight/" + msg.payload.ac.flight.trim()
];
if (elevation == "ground"){
    elevation = "0.0"
};
let hae = elevation;
const ce = typeof msg.payload.ac.nac_p !== 'undefined' ? msg.payload.ac.nac_p : '999999';
const le = typeof msg.payload.ac.nac_v !== 'undefined' ? msg.payload.ac.nac_v : '999999';
const course = typeof msg.payload.ac.track !== 'undefined' ? msg.payload.ac.track : "0.0";
const speed = typeof msg.payload.ac.gs !== 'undefined' ? msg.payload.ac.gs * 0.514444 : "0.0";
if (hae == "" || hae == null) {
    hae = "999999"
};
const nameID = (msg.payload.ac.flight.trim() + "-" + (type || hexid)).trim()
const category = msg.payload.ac.category;
let attitude;
let affil;
if (msg.payload.ac.dbFlags == 1) {
    attitude = "f";
    affil = "M";
} else {
    attitude = "n";
    affil = "C";
}
const categoryToCoT = {
    "1": "a-" + attitude + "-A-" + affil + "-F",
    "2": "a-" + attitude + "-A-" + affil + "-F",
    "3": "a-" + attitude + "-A-" + affil + "-F",
    "4": "a-" + attitude + "-A-" + affil + "-F",
    "5": "a-" + attitude + "-A-" + affil + "-F",
    "A1": "a-" + attitude + "-A-" + affil + "-F",
    "A2": "a-" + attitude + "-A-" + affil + "-F",
    "A3": "a-" + attitude + "-A-" + affil + "-F",
    "A4": "a-" + attitude + "-A-" + affil + "-F",
    "A5": "a-" + attitude + "-A-" + affil + "-F",
    //Fixed
    "6": "a-" + attitude + "-A-M-F-F",
    "A6": "a-" + attitude + "-A-M-F-F",
    //Rotary
    "7": "a-" + attitude + "-A-" + affil + "-H",
    "A7": "a-" + attitude + "-A-" + affil + "-H",
    //Glider
    "9": "a-" + attitude + "-A-" + affil + "-F",
    "B1": "a-" + attitude + "-A-" + affil + "-F",
    "10": "a-" + attitude + "-A-" + affil + "-L",
    "B2": "a-" + attitude + "-A-" + affil + "-L",
    "14": "a-" + attitude + "-A-M-F-Q",
    "B6": "a-" + attitude + "-A-M-F-Q",
    "15": "a-n-A-C-U",
    "B7": "a-n-A-C-U",
    "17": "a-" + attitude + "-G-E-V-C-U",
    "18": "a-" + attitude + "-G-E-V-C-U",
    "C1": "a-" + attitude + "-G-E-V-C-U",
    "C2": "a-" + attitude + "-G-E-V-C-U",
    "19": "a-" + attitude + "-G-I-U-T-com-tow",
    "20": "a-" + attitude + "-G-I-U-T-com-tow",
    "C3": "a-" + attitude + "-G-I-U-T-com-tow",
    "C4": "a-" + attitude + "-G-I-U-T-com-tow"
}
const cotType = categoryToCoT[category] || "a-" + attitude + "-A-" + affil;
const contact = {
    contact: [
        nameID.trim(), //Callsign
        desc,
        remarks
    ]
};
const track = {
    track: [
        nameID.trim(), //Callsign
        course,
        speed
    ]
};
const event = {
    event: [
        time, //Time/StartTime
        latitude,
        longitude,
        hae,
        ce,
        le,
        nameID.trim(), //Callsign
        cotType
    ]
}

return [
    { payload: contact, 
      parts: msg.parts },

    { payload: track,
      parts: msg.parts },

    { payload: event,
      parts: msg.parts }
];

if (parseFloat(msg.payload.event[1]) === 0 && 
parseFloat(msg.payload.event[2]) === 0 || 
parseFloat(msg.payload.track[2]) === 0) {
    return null;  // Drop the message
}
if (msg.payload.contact[0] && 
msg.payload.contact[0].includes('-undefined')) {
    return null; // Drop the message
}
const start = new Date(Date.now()).toISOString();
const staleTime = new Date(Date.now() + ((2 * 60 * 1000))).toISOString();;

msg.payload = {
    "event": {
        "_attributes": {
            "version": "2.0",
            "uid": msg.payload.contact[0],
            "type": msg.payload.event[7],
            "how": "m-p",
            "time": start,
            "start": start,
            "stale": staleTime,
            "access": "UNCLASSIFIED"
        },
        "point" : {
            "_attributes": {
                "lat": msg.payload.event[1],
                "lon": msg.payload.event[2],
                "hae": msg.payload.event[3],
                "ce": msg.payload.event[4],
                "le": msg.payload.event[5]
            }
        },
        "detail": {
            "track": {
                "_attributes": {
                "course": msg.payload.track[1],
                "speed": msg.payload.track[2],
                "slope": "999999.0"
                }
            },
            "contact": {
                "_attributes": {
                    "callsign": msg.payload.contact[0]
                }
            },
            "remarks": msg.payload.contact[2] +
            "\n#OSINT_ADSB"
        }
    }
}
return msg;
